// Writes src/version.ts from package.json so the handshake always reports
// the published version. Runs as the first step of `npm run build`.
const fs = require('fs');
const path = require('path');
const { version } = require('../package.json');

fs.writeFileSync(
  path.join(__dirname, '../src/version.ts'),
  '// Generated by scripts/write-version.js from package.json — do not edit.\n' +
    `export const SDK_VERSION = '${version}';\n`,
);
